    'stock-listing': t('header.title.stockListing', 'Stock Listing'),
    countries: t('header.title.countries', 'Countries'),
    'country-admin-levels': t('header.title.countryAdminLevels', 'Country Admin Levels'),
    'shop-users': t('header.title.shopUsers', 'Shop Users'),
    'super-users': t('header.title.superUsers', 'Super Users'),
    permissions: t('header.title.permissions', 'Permissions'),
    roles: t('header.title.roles', 'Manage Roles'),
    shops: t('header.title.shops', 'Shop Management'),
    'shop-profile': t('header.title.shopProfile', 'Shop Profile'),
    'shop-surveillance': 'Shop Surveillance',
    'finances-income-statement': t('header.title.financesIncomeStatement', 'Income Statements'),
    'finances-balance-sheet': t('header.title.financesBalanceSheet', 'Balance Sheets'),
    'finances-cash-flow': t('header.title.financesCashFlow', 'Cash Flow Statements'),
    'income-statement-detail': t('header.title.incomeStatementDetail', 'Financial Dashboard'),
    'reports-messages': 'Messages',
    'reports-calls': 'Call Records',
    'reports-daily-sales': 'Daily Sales Report',
    'reports-product-profile': 'Product Profile Report',
    'client-list': 'Client List',
    'client-wallets': 'Client Wallets',
    'system-message-settings': 'Message Settings',
    'wallet-settings': 'Wallet Settings',
    'product-chain-products': 'Products',
    'product-chain-manufacturers': 'Manufacturers',
    'product-chain-distributors': 'Distributors',
    'product-chain-suppliers': 'Suppliers',
  };

  const handleViewShopProfile = (shop: Shop) => {
    setSelectedShop(shop);
    onNavigate('shop-profile');
  };

  const handleViewIncomeStatementDetail = (shop: Shop) => {
    setSelectedShop(shop);
    onNavigate('income-statement-detail');
  }

  const renderContent = () => {
    const allUsers: (ShopUser | SuperUser)[] = [...shopUsers, ...mockSuperUsers];
    switch (activeView) {
      case 'profile':
        return <ProfilePage theme={theme} user={user} setUser={setUser} />;
      case 'settings':
        return <SettingsPage theme={theme} />;
      case 'settings-cameras':
        return <CameraSettingsPage theme={theme} cameraDevices={cameraDevices} setCameraDevices={setCameraDevices} shops={shops} users={allUsers} currentUser={currentUser} />;
      case 'settings-api':
        return <ApiSettingsPage theme={theme} currentUser={currentUser} />;
      case 'settings-calls':
        return <CallSettingsPage theme={theme} allowCalls={allowCalls} setAllowCalls={setAllowCalls} allowMicrophone={allowMicrophone} setAllowMicrophone={setAllowMicrophone} currentUser={currentUser} />;
      case 'id-verification':
        return <IDVerificationPage theme={theme} requests={verificationRequests} setRequests={setVerificationRequests} />;
      case 'countries':
        return <CountriesPage theme={theme} countries={countries} setCountries={setCountries} />;
      case 'country-admin-levels':
        return <CountryAdminLevelsPage theme={theme} countries={countries} setCountries={setCountries} />;
      case 'shop-users':
        return <ShopUsersPage theme={theme} shopRoles={shopRoles} setVerificationRequests={setVerificationRequests} shopUsers={shopUsers} setShopUsers={setShopUsers} currentUser={currentUser} />;
      case 'super-users':
        return <SuperUsersPage theme={theme} />;
      case 'permissions':
        return <PermissionsPage theme={theme} shopRoles={shopRoles} superUserRoles={superUserRoles} setShopRoles={setShopRoles} setSuperUserRoles={setSuperUserRoles} />;
       case 'stock-purchase':
        return <StockPurchasePage theme={theme} currentUser={currentUser} />;
      case 'roles':
        return <RolesPage theme={theme} shopRoles={shopRoles} superUserRoles={superUserRoles} setShopRoles={setShopRoles} setSuperUserRoles={setSuperUserRoles} shopUsers={shopUsers} setShopUsers={setShopUsers} />;
      case 'shops':
        return <ShopsPage theme={theme} shops={shops} setShops={setShops} onSelectShop={handleViewShopProfile} countries={countries} users={allUsers} onViewStatement={handleViewIncomeStatementDetail} />;
      case 'shop-profile':
        return <ShopProfilePage theme={theme} shop={selectedShop} users={allUsers} onNavigate={onNavigate} />;
      case 'shop-surveillance':
        return <ShopSurveillancePage theme={theme} cameraDevices={cameraDevices} />;
      case 'finances-income-statement':
        return <IncomeStatementPage theme={theme} onViewStatement={handleViewIncomeStatementDetail} />;
      case 'finances-balance-sheet':
        return <BalanceSheetPage theme={theme} onSelectShop={handleViewShopProfile} />;
      case 'finances-cash-flow':
        return <CashFlowPage theme={theme} onSelectShop={handleViewShopProfile} />;
      case 'income-statement-detail':
        return <IncomeStatementDetailPage theme={theme} shop={selectedShop} onNavigate={onNavigate} />;
      case 'reports-messages':
        return <MessagesPage theme={theme} currentUser={currentUser} users={allUsers} shops={shops} countries={countries} trackedKeywords={trackedKeywords} />;
      case 'reports-calls':
        return <ReportsCallsPage theme={theme} callRecords={callRecords} deletedCallRecords={deletedCallRecords} onDeleteCall={onDeleteCall} currentUser={currentUser} />;
      case 'reports-daily-sales':
        return <DailySalesPage theme={theme} />;
      case 'reports-product-profile':
        return <ProductProfilePage theme={theme} />;
      case 'client-list':
        return <ClientsPage theme={theme} currentUser={currentUser} />;
      case 'client-wallets':
        return <ClientWalletsPage theme={theme} shops={shops} currentUser={currentUser} />;
      case 'wallet-settings':
        return <WalletSettingsPage theme={theme} shops={shops} setShops={setShops} />;
      case 'system-message-settings':
        return <MessageSettingsPage theme={theme} users={mockSuperUsers} shops={shops} countries={countries} trackedKeywords={trackedKeywords} setTrackedKeywords={setTrackedKeywords} />;
      case 'product-chain-products':
        return <ProductsPage theme={theme} />;
      case 'product-chain-manufacturers':
        return <div className="p-6">Manufacturers Page (Placeholder)</div>;
      case 'product-chain-distributors':
        return <div className="p-6">Distributors Page (Placeholder)</div>;
      case 'product-chain-suppliers':
        return <div className="p-6">Suppliers Page (Placeholder)</div>;
      case 'stock-listing':
        return (
          <div className={`p-6 rounded-lg ${theme === 'dark' ? 'bg-slate-900' : 'bg-white'}`}>
            <h2 className="text-xl font-bold">Stock Listing</h2>
            <p className={`mt-2 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>This page is under construction.</p>
          </div>
        );
      case 'dashboard-system':
        return <SystemUsageDashboard theme={theme} />;
      case 'dashboard-traffic':
        return <TrafficDashboard theme={theme} />;
      case 'dashboard':
      case 'dashboard-users':
      default:
        return <Dashboard theme={theme} shopRoles={shopRoles} superUserRoles={superUserRoles} shopUsers={shopUsers} superUsers={mockSuperUsers} notifications={notifications} onNavigate={onNavigate} trackedKeywords={trackedKeywords} />;
    }
  };

  return (
    <div className="p-6 h-full flex flex-col">
      <div className="flex justify-between items-center mb-6 flex-shrink-0">
        <div className="flex items-center">
          <button onClick={onToggleSidebar} className={`p-2 mr-4 rounded-md ${theme === 'dark' ? 'text-slate-400 hover:bg-slate-700' : 'text-slate-500 hover:bg-slate-200'}`}>
            <Icon name="hamburger" className="h-6 w-6" />
          </button>
          <h1 className={`text-2xl font-semibold ${theme === 'dark' ? 'text-slate-100' : 'text-slate-800'}`}>{titles[activeView]}</h1>
        </div>
        <div className="flex items-center space-x-4">
          <LanguageSelector theme={theme} language={language} onLanguageChange={setLanguage} />
          <NotificationDropdown theme={theme} notifications={notifications} setNotifications={setNotifications} />
          <ProfileDropdown theme={theme} user={user} onNavigate={onNavigate} />
        </div>
      </div>
      <div className="flex-grow overflow-y-auto">
        {renderContent()}
      </div>
    </div>
  );
};

export default MainContent;
